import json
import os
import hashlib

class CredentialsStorage:
    def __init__(self, filename="credentials.json"):
        self.filename = filename
        if not os.path.exists(self.filename):
            with open(self.filename, 'w') as f:
                json.dump([], f, indent=4)

    def _load_credentials(self):
        with open(self.filename, 'r') as f:
            return json.load(f)

    def _save_credentials(self, credentials):
        with open(self.filename, 'w') as f:
            json.dump(credentials, f, indent=4)

    def _hash_password(self, password):
        return hashlib.sha256(password.encode('utf-8')).hexdigest()

    def add_user(self, username, password, role):
        """
        Add a new user with role 'author' or 'reader'.
        """
        credentials = self._load_credentials()
        if any(user['username'] == username for user in credentials):
            raise ValueError("Username already exists")
        hashed_password = self._hash_password(password)
        credentials.append({
            "username": username,
            "password": hashed_password,
            "role": role
        })
        self._save_credentials(credentials)

    def verify_user(self, username, password, role=None):
        """
        Verify username and password. If role is given, also check role.
        """
        credentials = self._load_credentials()
        hashed_password = self._hash_password(password)
        for user in credentials:
            if user['username'] == username and user['password'] == hashed_password:
                if role is None or user['role'] == role:
                    return True
        return False

    def get_user_role(self, username):
        credentials = self._load_credentials()
        for user in credentials:
            if user['username'] == username:
                return user['role']
        return None

